snippet_css:
:root{
  --bg: #F8F3E9;
  --fg: #3E3328;
  --muted: #5B4B3B;
  --surface: #EFE7D6;
  --border: #D9CCB4;
  --accent: #4F5A3D;
  --accent-fg: #FFFFFF;
  --accent-grad: linear-gradient(90deg,#B79C7B,#8A8F6A);
  --radius: 6px;
  --radius-sm: 4px;
  --shadow: 0 14px 34px rgba(62,51,40,.10);
  --btn-shadow: 0 2px 0 rgba(62,51,40,.16);
  --art-bg: linear-gradient(115deg,rgba(255,236,190,.45) 0 40px,transparent 40px 90px),linear-gradient(180deg,#EADFCB,#C7D6DE);
  --media-bg: linear-gradient(180deg,#EFE7D6,#D9CCB4);
  --cta-bg: #EFE7D6;
  --input-bg: #FFFFFF;
  --ok: #3F6B4E;
  --warn: #A6483A;
  --font-display: 'Cormorant Garamond','Noto Serif TC',serif;
  --font-body: Lora,'Noto Serif TC',serif;
  --font-mono: ui-monospace,'SF Mono',Menlo,monospace;
  --focus-ring: var(--accent);
}

